<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>商品单位</h2><p>统一计量字典。已引用单位不能改变含义；停用只限制新选用。</p></div><Button type="primary" :disabled="blocked" @click="edit(null)">新增单位</Button></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>单位名称<Input v-model="searchDraft" placeholder="搜索全量单位字典" @on-enter="search"/></label><label>启停状态<Select v-model="enabledDraft" clearable><Option value="true">启用</Option><Option value="false">停用</Option></Select></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><Table class="s1-list-table" v-compact-table :data="visibleRows" :columns="columns" :loading="loading" no-data-text="没有符合条件的单位"><template slot="state" slot-scope="{row}"><Tag :color="row.enabled?'green':'default'">{{row.enabled?'启用':'停用'}}</Tag></template><template slot="operations" slot-scope="{row}"><div class="ui-actions"><Button size="small" :disabled="blocked" @click="edit(row)">编辑</Button><Button size="small" :disabled="blocked" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</Button><Button size="small" @click="history(row)">历史</Button></div></template></Table><Page class="ui-pagination" :total="filtered.length" :current="page" :page-size="size" show-total @on-change="page=$event"/><Modal v-model="show" :title="editing?'编辑单位':'新增单位'" :mask-closable="false" footer-hide><div class="s1-ui"><Form ref="unitForm" :model="form" :rules="rules" :label-width="90"><FormItem label="单位名称" prop="name"><Input v-model="form.name" maxlength="10" :disabled="blocked||!!(editing&&editing.referencedGoods)"/><p v-if="editing&&editing.referencedGoods" class="ui-note">此单位已被商品引用，不能改变原义。</p></FormItem><FormItem label="变更原因" prop="reason"><Input v-model="form.reason" type="textarea" maxlength="500" :disabled="blocked"/></FormItem></Form><p class="ui-error" v-if="error">{{error}}</p><footer class="ui-form-footer"><Button @click="show=false;dirty=false">取消</Button><Button type="primary" :disabled="pending" :loading="busy" @click="save">保存单位</Button></footer></div></Modal><Drawer v-model="historyShow" title="单位版本历史" width="80"><div v-if="selected" class="s1-ui"><h2>{{selected.item.name}}</h2><p class="ui-meta">编号 {{selected.item.id}} · 商品引用 {{selected.item.referencedGoods}}</p><HistoryTable :records="selected.history.map(h=>({...h,name:h.snapshot.name,enabledText:h.snapshot.enabled?'启用':'停用'}))" :columns="historyColumns"/></div></Drawer></Card></template>
<script>import page from './page';import demo from './demo-data.cjs';import PageStatus from './components/PageStatus';import HistoryTable from './components/HistoryTable';export default {mixins:[page],components:{PageStatus,HistoryTable},data:()=>({formBaseline:'',show:false,historyShow:false,editing:null,searchDraft:'',enabledDraft:'',query:'',enabled:'',form:{name:'',reason:''},rules:{name:[{required:true,message:'请填写1～10字单位名称',trigger:'blur'}],reason:[{required:true,message:'请填写原因',trigger:'blur'}]},columns:[{title:'单位名称',key:'name',minWidth:140},{title:'状态',slot:'state',width:100},{title:'引用商品数',key:'referencedGoods',width:120},{title:'版本',key:'version',width:80},{title:'操作',slot:'operations',minWidth:250}],historyColumns:[{title:'版本',key:'version',width:80},{title:'名称',key:'name',minWidth:150},{title:'状态',key:'enabledText',width:100},{title:'原因',key:'reason',minWidth:200},{title:'时间',slot:'time',minWidth:185}]}),watch:{form:{deep:true,handler(value){if(this.show)this.dirty=JSON.stringify(value)!==this.formBaseline;}}},computed:{filtered(){return demo.unitRows(this.records,!this.demoActive).filter(r=>(!this.query||r.name.toLowerCase().includes(this.query.toLowerCase()))&&(this.enabled===''||r.enabled===(this.enabled==='true')));},visibleRows(){return this.filtered.slice((this.page-1)*this.size,this.page*this.size);}},mounted(){this.initializeList(['query','enabled']);this.searchDraft=this.query;this.enabledDraft=this.enabled;this.reload();},methods:{reload(){return this.load('/units');},search(){this.query=this.searchDraft;this.enabled=this.enabledDraft||'';this.page=1;this.remember(['query','enabled']);},reset(){this.searchDraft='';this.enabledDraft='';this.search();},edit(row){this.editing=row;this.form={name:row?row.name:'',reason:''};this.error='';this.formBaseline=JSON.stringify(this.form);this.dirty=false;this.show=true;},save(){this.$refs.unitForm.validate(async valid=>{if(!valid)return;try{const result=await this.run('/units'+(this.editing?'/'+this.editing.id:''),{...this.form,...(this.editing?{expectedVersion:this.editing.version}:{})},this.editing?'PUT':'POST');if(result){this.show=false;await this.reload();}}catch(_){}});},async toggle(row){const result=await this.command('/units/'+row.id+(row.enabled?'/disable':'/enable'),row.enabled?'停用单位':'启用单位',{expectedVersion:row.version},row.name+'；不改写已有商品的单位语义。');if(result)await this.reload();},history(row){this.historyShow=true;this.selected=null;return this.latest(()=>this.read('/units/'+row.id),v=>{this.selected=v;});}}};</script>
